const db = {
  users: [{ id: 'u1', email: 'ana@example.com', admin: true }, { id: 'u2', email: 'ben@example.com', admin: false }],
  projects: [{ id: 'p1', name: 'Website', ownerId: 'u1' }, { id: 'p2', name: 'Mobile', ownerId: 'u2' }],
